    let gust = blade_noise(root * 0.11 - DOWNWIND * time * 0.3) * 0.65 + blade_noise(root * 0.37 - DOWNWIND * time * 0.5) * 0.35;
    let blowing = smoothstep(0.42, 0.78, gust);
